class Solution:
    def countLocalMaximums(self, matrix: List[List[int]]) -> int:
        n, m = len(matrix), len(matrix[0])
        ans = 0
        for i in range(n):
            for j in range(m):
                x = matrix[i][j]
                if x == 0:
                    continue
                ok = True
                for r in range(max(0, i - x), min(n - 1, i + x) + 1):
                    for c in range(max(0, j - x), min(m - 1, j + x) + 1):
                        if abs(r - i) == x and abs(c - j) == x:
                            continue
                        if matrix[r][c] > x:
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    ans += 1
        return ans

