class Solution:
    def countLocalMaximums(self, matrix: List[List[int]]) -> int:
        n, m = len(matrix), len(matrix[0])
        lg = [0] * (max(n, m) + 1)
        for i in range(2, len(lg)):
            lg[i] = lg[i >> 1] + 1
        K1, K2 = lg[n] + 1, lg[m] + 1
        st = [[[r[:] for r in matrix]]]
        for a in range(1, K1):
            h = 1 << (a - 1)
            prev = st[-1][0]
            st.append([[max(prev[i][j], prev[i + h][j]) for j in range(m)] for i in range(n - h)])
        for a in range(K1):
            for b in range(1, K2):
                h = 1 << (b - 1)
                prev = st[a][b - 1]
                st[a].append([[max(row[j], row[j + h]) for j in range(len(row) - h)] for row in prev])
        def q(r1, r2, c1, c2):
            if r1 > r2 or c1 > c2:
                return -1
            a, b = lg[r2 - r1 + 1], lg[c2 - c1 + 1]
            la, lb = 1 << a, 1 << b
            s = st[a][b]
            return max(s[r1][c1], s[r1][c2 - lb + 1], s[r2 - la + 1][c1], s[r2 - la + 1][c2 - lb + 1])
        ans = 0
        for i in range(n):
            for j in range(m):
                x = matrix[i][j]
                if x == 0:
                    continue
                M = max(q(max(0, i - x), min(n - 1, i + x), max(0, j - x + 1), min(m - 1, j + x - 1)),
                        q(max(0, i - x + 1), min(n - 1, i + x - 1), max(0, j - x), j),
                        q(max(0, i - x + 1), min(n - 1, i + x - 1), min(m - 1, j + x), m - 1))
                if M <= x:
                    ans += 1
        return ans

