class Solution {
public:
    int countLocalMaximums(vector<vector<int>>& matrix) {
        int n = matrix.size(), m = matrix[0].size();
        int MX = max(n, m);
        vector<int> lg(MX + 1, 0);
        for (int i = 2; i <= MX; i++) lg[i] = lg[i >> 1] + 1;
        int K1 = lg[n] + 1, K2 = lg[m] + 1;
        vector<vector<vector<vector<int>>>> st(K1,
            vector<vector<vector<int>>>(K2));
        st[0][0] = matrix;
        for (int a = 1; a < K1; a++) {
            int h = 1 << (a - 1);
            auto& p = st[a - 1][0];
            st[a][0].assign(n - h, vector<int>(m));
            for (int i = 0; i < n - h; i++)
                for (int j = 0; j < m; j++)
                    st[a][0][i][j] = max(p[i][j], p[i + h][j]);
        }
        for (int a = 0; a < K1; a++)
            for (int b = 1; b < K2; b++) {
                int h = 1 << (b - 1);
                auto& p = st[a][b - 1];
                st[a][b].assign(p.size(), vector<int>(p[0].size() - h));
                for (int i = 0; i < (int)p.size(); i++)
                    for (int j = 0; j < (int)p[0].size() - h; j++)
                        st[a][b][i][j] = max(p[i][j], p[i][j + h]);
            }
        auto q = [&](int r1, int r2, int c1, int c2) {
            if (r1 > r2 || c1 > c2) return -1;
            int a = lg[r2 - r1 + 1], b = lg[c2 - c1 + 1];
            int la = 1 << a, lb = 1 << b;
            auto& s = st[a][b];
            return max(max(s[r1][c1], s[r1][c2 - lb + 1]),
                       max(s[r2 - la + 1][c1], s[r2 - la + 1][c2 - lb + 1]));
        };
        int ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                int x = matrix[i][j];
                if (!x) continue;
                int M = max(q(max(0, i - x), min(n - 1, i + x), max(0, j - x + 1), min(m - 1, j + x - 1)),
                            max(q(max(0, i - x + 1), min(n - 1, i + x - 1), max(0, j - x), j),
                                q(max(0, i - x + 1), min(n - 1, i + x - 1), min(m - 1, j + x), m - 1)));
                if (M <= x) ans++;
            }
        return ans;
    }
};

