class Solution {
    int[][][][] st;
    int[] lg;
    public int countLocalMaximums(int[][] matrix) {
        int n = matrix.length, m = matrix[0].length;
        int MX = Math.max(n, m);
        lg = new int[MX + 1];
        for (int i = 2; i <= MX; i++) lg[i] = lg[i >> 1] + 1;
        int K1 = lg[n] + 1, K2 = lg[m] + 1;
        st = new int[K1][K2][][];
        st[0][0] = matrix;
        for (int a = 1; a < K1; a++) {
            int h = 1 << (a - 1);
            int[][] p = st[a - 1][0];
            st[a][0] = new int[n - h][m];
            for (int i = 0; i < n - h; i++)
                for (int j = 0; j < m; j++)
                    st[a][0][i][j] = Math.max(p[i][j], p[i + h][j]);
        }
        for (int a = 0; a < K1; a++)
            for (int b = 1; b < K2; b++) {
                int h = 1 << (b - 1);
                int[][] p = st[a][b - 1];
                st[a][b] = new int[p.length][p[0].length - h];
                for (int i = 0; i < p.length; i++)
                    for (int j = 0; j < p[0].length - h; j++)
                        st[a][b][i][j] = Math.max(p[i][j], p[i][j + h]);
            }
        int ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                int x = matrix[i][j];
                if (x == 0) continue;
                int M = Math.max(q(Math.max(0, i - x), Math.min(n - 1, i + x), Math.max(0, j - x + 1), Math.min(m - 1, j + x - 1)),
                            Math.max(q(Math.max(0, i - x + 1), Math.min(n - 1, i + x - 1), Math.max(0, j - x), j),
                                q(Math.max(0, i - x + 1), Math.min(n - 1, i + x - 1), Math.min(m - 1, j + x), m - 1)));
                if (M <= x) ans++;
            }
        return ans;
    }
    int q(int r1, int r2, int c1, int c2) {
        if (r1 > r2 || c1 > c2) return -1;
        int a = lg[r2 - r1 + 1], b = lg[c2 - c1 + 1];
        int la = 1 << a, lb = 1 << b;
        int[][] s = st[a][b];
        return Math.max(Math.max(s[r1][c1], s[r1][c2 - lb + 1]),
                        Math.max(s[r2 - la + 1][c1], s[r2 - la + 1][c2 - lb + 1]));
    }
}

