var countLocalMaximums = function(matrix) {
    const n = matrix.length, m = matrix[0].length;
    const MX = Math.max(n, m);
    const lg = new Array(MX + 1).fill(0);
    for (let i = 2; i <= MX; i++) lg[i] = lg[i >> 1] + 1;
    const K1 = lg[n] + 1, K2 = lg[m] + 1;
    const st = [[matrix.map(r => r.slice())]];
    for (let a = 1; a < K1; a++) {
        const h = 1 << (a - 1), p = st[a - 1][0], cur = [];
        for (let i = 0; i < n - h; i++) {
            const row = new Array(m);
            for (let j = 0; j < m; j++) row[j] = Math.max(p[i][j], p[i + h][j]);
            cur.push(row);
        }
        st.push([cur]);
    }
    for (let a = 0; a < K1; a++)
        for (let b = 1; b < K2; b++) {
            const h = 1 << (b - 1), p = st[a][b - 1], cur = [];
            for (const row of p) {
                const nr = new Array(row.length - h);
                for (let j = 0; j < nr.length; j++) nr[j] = Math.max(row[j], row[j + h]);
                cur.push(nr);
            }
            st[a].push(cur);
        }
    const q = (r1, r2, c1, c2) => {
        if (r1 > r2 || c1 > c2) return -1;
        const a = lg[r2 - r1 + 1], b = lg[c2 - c1 + 1];
        const la = 1 << a, lb = 1 << b, s = st[a][b];
        return Math.max(s[r1][c1], s[r1][c2 - lb + 1], s[r2 - la + 1][c1], s[r2 - la + 1][c2 - lb + 1]);
    };
    let ans = 0;
    for (let i = 0; i < n; i++)
        for (let j = 0; j < m; j++) {
            const x = matrix[i][j];
            if (!x) continue;
            const M = Math.max(
                q(Math.max(0, i - x), Math.min(n - 1, i + x), Math.max(0, j - x + 1), Math.min(m - 1, j + x - 1)),
                q(Math.max(0, i - x + 1), Math.min(n - 1, i + x - 1), Math.max(0, j - x), j),
                q(Math.max(0, i - x + 1), Math.min(n - 1, i + x - 1), Math.min(m - 1, j + x), m - 1));
            if (M <= x) ans++;
        }
    return ans;
};
